window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d01_prj14"]={"title": "ЗФ-151 006-ИГИ2.1.3", "pages": 65, "pagesTxt": ["[стр. 1]\nЗаказчик – ЗФ ПАО «ГМК Норильский Никель»\r\nТехнический отчет по результатам\r\nинженерно-геологических и геокриологических изысканий\r\nпо объекту: \r\n«Выполнение комплекса работ по изучению фильтрационных \r\nи температурных режимов хвостохранилища Талнахской \r\nобогатительной фабрики Заполярного филиала Публичного \r\nакционерного общества «Горно-металлургической компании \r\n«Норильский никель»\r\nТом 2.1.3\r\nГлавный инженер проекта А.М. Бабич\r\n2023\r\nОБЩЕСТВО С ОГРАНИЧЕННОЙ ОТВЕТСТВЕННОСТЬЮ\r\n«МИГРУП ПРОЕКТ»", "[стр. 2]\nАО «КРАСНОЯРСКАЯ БУРОВАЯ КОМПАНИЯ»\r\nАО «КБК»\r\nВыполнение комплекса работ по изучению фильтрационных и \r\nтемпературных режимов хвостохранилища \r\nТалнахской обогатительной фабрики Заполярного филиала \r\nПубличного акционерного общества «Горно-металлургической \r\nкомпании «Норильский никель»\r\nПРОЕКТНАЯ ДОКУМЕНТАЦИЯ\r\nРАБОЧАЯ ДОКУМЕНТАЦИЯ\r\nИнженерные изыскания\r\nТехнический отчет по результатам инженерно-геологических, \r\nгидрогеологических и геокриологических изысканий\r\nТекстовая часть. Результаты рекогносцировочного \r\nобследования\r\nЗФ-151/006-ИГИ2.1.3\r\nИзм. № док Подп. Дата\r\nг. Красноярск\r\n2023 г.", "[стр. 3]\nИнв. № подл. Взам. Инв. № Подп. и дата\r\nАО «КРАСНОЯРСКАЯ БУРОВАЯ КОМПАНИЯ»\r\nАО «КБК»\r\nВыполнение комплекса работ по изучению \r\nфильтрационных и температурных режимов хвостохранилища \r\nТалнахской обогатительной фабрики Заполярного \r\nфилиала Публичного акционерного общества \r\n«Горно-металлургической компании \r\n«Норильский никель»\r\nПРОЕКТНАЯ ДОКУМЕНТАЦИЯ\r\nРАБОЧАЯ ДОКУМЕНТАЦИЯ\r\nИнженерные изыскания\r\nТехнический отчет по результатам инженерно￾геологических, гидрогеологических и геокриологических \r\nизысканий\r\nТекстовая часть. Результаты рекогносцировочного \r\nобследования\r\nЗФ-151/006-ИГИ2.1.3\r\nГенеральный\r\nдиректор АО «КБК» _________________ А.В. Гусев\r\nг. Красноярск\r\n2023 г.", "[стр. 4]\n2\r\nИнв. № подл. Взам. Инв. № Подп. и дата\r\nСписок исполнителей\r\nИсполнители:\r\nИнженерная геология\r\nИнженер-геолог Н.А. Бровченко\r\n(подпись, дата)\r\nИнженер-геолог И.А. Спиридонова\r\n(подпись, дата)\r\nИнженер-геолог П.С. Бирюля\r\n(подпись, дата)\r\nВедущий-геолог Л. А. Чичканова\r\n(подпись, дата)\r\nВедущий геолог Т.В. Добровольская\r\n(подпись, дата)\r\nГлавный специалист по \r\nгеологии Н.А. Зарипова\r\nВедущий гидрогеолог\r\n(подпись, дата)\r\nА.А. Булатов\r\n(подпись, дата)\r\nНормоконтроль Д.А. Ларкин\r\n(подпись, дата)\r\nНачальник отдела \r\nинженерных изысканий Р.Е. Ткачев\r\n(подпись, дата)\r\nДиректор А.В. Гусев\r\n(подпись, дата)", "[стр. 5]\n3\r\nСтадия Лист\r\nИ\r\nЛистов\r\n1\r\nАО «КБК»\r\nРазработал Чичканова\r\nЗарипова\r\nН.контр. Ларкин\r\nИзм. Кол.уч. Лист № док. Подп. Дата\r\n01.23\r\n01.23\r\n01.23\r\nЗФ-151/006-ИГИ2.1.3-С\r\nСодержание тома\r\nИнв. № подл. Взам. Инв. № Подп. и дата\r\nСогласовано\r\nСодержание тома\r\nОбозначение Наименование Примечание\r\nЗФ-151/006-ИГИ2.1.3-С Содержание тома 2\r\nЗФ-151/006-СД Состав документации 3\r\nЗФ-151/006-ИГИ2.1.3-Т Результаты рекогносцировочного обследования 5", "[стр. 6]\n4\r\nСтадия Лист\r\nИ\r\nЛистов\r\n1\r\nАО «КБК»\r\nРазработал Чичканова\r\nЗарипова\r\nН.контр. Ларкин\r\nИзм. Кол.уч. Лист № док. Подп. Дата\r\n01.23\r\n01.23\r\n01.23\r\nЗФ-151/006-СД\r\nСостав документации\r\nИнв. № подл. Взам. Инв. № Подп. и дата\r\nСогласовано\r\nСостав документации\r\nНомер\r\nтома\r\nЧасть Книга Обозначение Наименование Приме\r\nчание\r\n1 - -\r\nЗФ-151/006-ИГДИ\r\nТехнический отчет по результатам \r\nинженерно-геологических, инженерно￾геокриологических и инженерно￾гидрогеологическим изысканий.\r\n2\r\n1\r\n1\r\nЗФ-151/006-\r\nИГИ2.1.1\r\nТехнический отчет по результатам \r\nинженерно-геологических, инженерно￾геокриологических и инженерно￾гидрогеологическим изысканий.\r\nТекстовая часть. Пояснительная записка. \r\nТекстовые приложения\r\n2\r\nЗФ-151/006-\r\nИГИ2.1.2\r\nТехнический отчет по результатам \r\nинженерно-геологических, инженерно￾геокриологических и инженерно￾гидрогеологическим изысканий.\r\nТекстовая часть. Текстовые приложения\r\n3\r\nЗФ-151/006-\r\nИГИ2.1.3\r\nТехнический отчет по результатам \r\nинженерно-геологических, инженерно￾геокриологических и инженерно￾гидрогеологическим изысканий.\r\nТекстовая часть. Результаты \r\nрекогносцировочного обследования\r\n2 1\r\nЗФ-151/006-\r\nИГИ2.2.1\r\nТехнический отчет по результатам \r\nинженерно-геологических, инженерно￾геокриологических и инженерно￾гидрогеологическим изысканий.\r\nГрафическая часть. Карта фактического \r\nматериала, инженерно-геологические \r\nпрофиля, геолого-литологические колонки\r\n3 - - ЗФ-151/006-ИГФИ Технический отчет по результатам \r\nинженерно-геофизических изысканий.", "[стр. 7]\nСтадия Лист\r\nИ\r\nЛистов\r\n58\r\nАО «КБК»\r\nРазработал Чичканова\r\nЗарипова\r\nН.контр. Ларкин\r\nИзм. Кол.уч. Лист № док. Подп. Дата\r\n01.23\r\n01.23\r\n01.23\r\nЗФ-151/006-ИГИ2.1.3-Т\r\nТекстовая часть\r\nИнв. № подл. Взам. Инв. № Подп. и дата\r\nСогласовано\r\n5\r\nСодержание\r\n1 Введение.......................................................................................................................................................... 6\r\n2 Изученность территории ............................................................................................................................. 9\r\n3 Краткая физико-географическая,геоморфологическая, геологическаяи гидрогеологическая \r\nхарактеристики района работ ....................................................................................................................... 14\r\n3.1 Физико-географическая характеристика .............................................................................. 14\r\n3.2 Климатическая характеристика............................................................................................. 15\r\n3.3 Гидрографическая характеристика района работ................................................................ 16\r\n3.4 Техническая характеристика объекта исследований........................................................... 19\r\n3.5 Географо-экономические условия производства работ. ..................................................... 21\r\n3.6 Современное состояние объекта изысканий ........................................................................ 21\r\n3.7 Экзогенные геологические, инженерно-геологические, криогенные процессы .............. 23\r\n3.8 Специфические грунты .......................................................................................................... 24\r\n3.9 Краткая характеристика техногенных условий района....................................................... 24\r\n4 Инженерно-геологическое, инженерно-гидрогеологическое рекогносцировочное \r\nобследование .................................................................................................................................................... 26\r\n5 Требования по охране труда и техники безопасности при проведении работ ............................. 62", "[стр. 8]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n2\r\nВзам. Инв. № Подп. и дата\r\n6\r\n1 Введение\r\nСогласно техническому заданию от 10.01.2022 г. ЗФ ПАО «ГМК «Норильский никель» \r\nнастоящей Программой предусматривается выполнение инженерно-геологических изысканий для \r\nоценки инженерно-геологических, геокриологических и гидрогеологических условий \r\nэксплуатации хвостохранилища с разработкой рекомендаций по обеспечению эксплуатационной \r\nнадежности и безопасности ограждающих сооружений, а также улучшение экологической \r\nситуации вокруг техногенного объекта.\r\nОбъект инженерно-геологических изысканий – хвостохранилище Талнахской \r\nобогатительной фабрики (ТОФ). Хвостохранилище ТОФ расположено в Красноярском крае, на \r\nтерритории муниципального образования «городской округ Норильск», в 5,5 км северо-западней \r\nгородского района Талнах. Территория городского округа краевого подчинения находится внутри \r\nтерритории муниципальное образование «Таймырский Долгано-Ненецкий район»\r\nИдентификационные сведения об объекте: хвостохранилище намывного типа, равнинное, \r\nсооружения объекта относятся к заграждениям гидротехнической защиты; относится к категории \r\nопасного производственного объекта. Уровень ответственности – повышенный. Класс ГТС – II \r\n(прил. Б (исключено изменением № 1 от 20.10.2016 г.) СП 58.13330.2012 \"Гидротехнические \r\nсооружения. Основные положения\").\r\nВид строительства: Реконструкция.\r\nСтадия проектирования: рабочая документация.\r\nМестоположение объекта изысканий: Красноярский край, в 5,5 км СЗ района Талнах \r\nНорильского городского округа.\r\nЗаказчик:\r\n- ЗФ ПАО «ГМК «Норильский никель».\r\nИсполнитель: \r\n- АО «Красноярская буровая компания», является членом саморегулируемой организации \r\nАссоциация «Изыскательские организации Сибири» (выписка из реестра СРО Ассоциации «ИОС» \r\n№ 249 от 19.04.2022 г. – прил.3).\r\nПредварительная характеристика ожидаемых воздействий объектов строительства на \r\nприродную среду с указанием пределов этих воздействий в пространстве и во времени (для особо \r\nопасных объектов): воздействия на окружающую среду устанавливаются по результатам \r\nизысканий.", "[стр. 9]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n3\r\nВзам. Инв. № Подп. и дата\r\n7\r\nВозможные типы воздействий на все компоненты природной среды на протяжении всего\r\nстроительства и эксплуатации:\r\n- механическое;\r\n- химическое;\r\n- физическое.\r\nВ состав гидротехнических сооружений хвостохранилища ТОФ, согласно проекта входят:\r\n- сооружения системы складирования хвостов (складирование хвостов, отстоя и осветления \r\nв отстойном пруду хвостохранилища оборотной воды).\r\n- сооружения системы гидротранспорта хвостов. \r\n- сооружения системы оборотного водоснабжения. \r\nДеятельность по инженерно-геологическим изысканиям будет происходить в пределах \r\nсооружений системы складирования хвостов и их оснований, к которым относятся:\r\n• верховая дамба (южный и восточный участки) - 4,66 км;\r\n• разделительная дамба - (от верховой до фильтрующей дамбы) - 2,8 км;\r\n• фильтрующая дамба - 2,0 км.\r\n• низовая дамба - 1,6 км.\r\nИные системы и элементы хвостохранилища не являются субъектами изысканий, поэтому в \r\nдальнейшем не упоминаются.\r\nМорфометрические характеристики хвостохранилища ТОФ:\r\n- площадь всего хвостохранилища – 10,95 км2\r\n;\r\n- площадь хвостохранилища 1 очереди строительства – 7,19 км2\r\n;\r\n- площадь отстойного пруда – 1,08 км2\r\n;\r\n- стороны отстойного пруда – длина верховой фильтрующей дамбы 1 очереди – 2000 м, \r\nдлина низовой водоудерживающей ограждающей дамбы 1 очереди – 1600 м, расстояние между \r\nгребнями дамб – 450 м, ширина водной поверхности – 250-420 м;\r\n- НПУ (нормальный подпорный уровень) – 45,5 м. абс;\r\n- УМО (уровень мертвого объема) – 40,5 м. абс.\r\n- объем воды отстойного пруда при НПУ=45,5 м. абс – 1,7 млн. м3\r\n;\r\n- максимальный гидравлический напор низовой дамбы – 10 м.\r\nЦель инженерно-геологических изысканий:\r\n- оценка инженерно-геологических, геокриологических и гидрогеологических условий \r\nэксплуатации хвостохранилища с разработкой рекомендаций по обеспечению эксплуатационной", "[стр. 10]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n4\r\nВзам. Инв. № Подп. и дата\r\n8\r\nнадежности и безопасности ограждающих сооружений, а также улучшение экологической \r\nситуации вокруг техногенного объекта.\r\nЗадачами работ являются: \r\n- изучение инженерно-геологических, геокриологических и гидрогеологических условий, \r\nгеологического строения и литологии отложений чаши хвостохранилища, тел дамб и их основания \r\nна глубину влияния нагрузки от сооружений и хвостов;\r\n- картирование проявлений инженерно-геологических процессов и явлений (природных и \r\nтехногенных);\r\n- изучение теплового состояния Низовой и Верховой дамб, локализация участков и \r\nустановление причин растепления и фильтрации в теле и основании дамб;\r\n- выделение инженерно-геологических элементов (ИГЭ), получение нормативных и \r\nрасчетных характеристик грунтов, необходимых для определения несущей способности пляжа;\r\n- определение водно-физических и физико-механических свойств хвостовых отложений в \r\nразличном состоянии обезвоживания и лежалости;\r\n- прогноз развития инженерно-геологических процессов, фильтрационного и \r\nтемпературного режима сооружения с разработкой рекомендаций по их локализации и \r\nминимизации;\r\n- прогноз развития фильтрационного и температурного режима сооружения с разработкой \r\nмероприятий по их локализации и минимизации;\r\n- определение несущей способности основания (пляжа) и устойчивости ограждающей \r\nдамбы;\r\n- разработка научно-обоснованных мероприятий по устранению фильтрационных \r\nпроцессов через тело и основание дамб; \r\n- разработка рекомендаций по обеспечению эксплуатационной надежности и безопасности \r\nограждающих сооружений, а также улучшению экологической ситуации вокруг техногенного \r\nобъекта;\r\n- составление топографического плана хвостохранилища м-ба 1:1000 с сечением \r\nгоризонталей 0,5 м в Кайерканской системе координат и Балтийской системе высот.\r\nПо завершению комплекса работ по изысканиям степень изученности инженерно￾геологических, гидрогеологических и геокриологических условий хвостохранилища ТОФ должна \r\nпозволить дать обоснованные рекомендации по разработке противофильтрационных мероприятий \r\nи уменьшению негативного влияния хвостохранилища на окружающую среду.", "[стр. 11]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n5\r\nВзам. Инв. № Подп. и дата\r\n9\r\n2 Изученность территории\r\n2.1 Геологическая изученность\r\nГеологосъемочными работами м-ба 1:200000 район г. Норильска и Талнаха был охвачен при \r\nсоздании Госгеолкарты СССР листа R-45-XXIII,-XXIV в 1959-1960 гг. Работы выполнялись силами \r\nпартий №№ 1, 2 и 3 Енисейской экспедиции НИИГА, работавших одновременно в различных \r\nчастях площади (Войцеховский В.Н., Соболев В.П., Гутарович В.Г., 1960 г.; Голубков В.С., Додин \r\nД.А., Начинкин Н.Г., 1960 г.; Марковский В.А., Архипов А.И., Куликов Ю.С.,1960 г.). В результате \r\nобобщения полученных материалов в 1962-1967 гг. НИИГА была составлена и издана \r\nГеологическая карта СССР, м-б 1:200000, серия Туруханская, листы R-45-XXIII, R-45-XXIV с \r\nобъяснительной запиской (Войцеховский В.Н., Иванова А.М., 1968 г.). Записка содержит описание \r\nгеологического строения, тектоники, геоморфологии, полезных ископаемых и подземных вод \r\nтерритории. \r\nГеологическая съемка м-ба 1:50000 листов R-45-93-А,-Б, R-45-94-А,-Б,-Г на площади \r\nТалнахского рудного узла (включая участок будущего хвостохранилища) проведена Талнахской \r\nгеолого-съемочной партией Норильской КГРЭ Красноярского ГУ в 1963-1966 гг. (Люлько В.А., \r\nГлушницкий О.Т., Лосев В.М., Говердовская Т.Г., 1965 г., 1967 г.). Съемка проведена с \r\nдешифрированием аэрофотоснимков, проходкой буровых скважин и горных выработок, \r\nметаллометрическим, донным и гидрохимическим опробованием. Наряду с решением вопросов \r\nрудоносности площади, произведено детальное возрастное и литолого-генетическое расчленение \r\nчетвертичных отложений. На смежной площади (листы R-45-93-В, -Г) в 1966-1969 гг. ГС-50 по \r\nизучению геологического строение долины р. Норильской проводила Вальковская партия \r\nНорильской КГРЭ Красноярского ГУ (Скобелин А.А., Амосов Ю.Н., Говердовская Т.Г., 1969 г.) \r\nВ 1994 г. ФГУП «Красноярскгеолсъемка» был обобщен обширный, накопленный за \r\nмноголетний период исследований, материал о геологическом строении и рудоносности \r\nНорильского рудного района в пределах листов R-45-XXII, R-45-XXIII, R-45-XXIX, R-45-XXVIII с \r\nсоставлением геологической карты района м-ба 1:200000 и объяснительной записки к ней. В 1999 \r\nг. карта и объяснительная записка были изданы (Струнин Б.М., Дюжиков О.А., Бармина О.А., 1999 \r\nг.).\r\nНа современном уровне, в региональном плане, материалы геологического изучения \r\nтерритории листа R-45 (Норильск) обобщены работами ФГУП «ВСЕГЕИ» в рамках объекта \r\nгеологического изучения территории РФ «Создание комплектов государственных геологических \r\nкарт масштаба 1:1000000 третьего поколения листов R-45 (Норильск), S-46 (р.Тарея), O-52", "[стр. 12]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n6\r\nВзам. Инв. № Подп. и дата\r\n10\r\n(Томмот)» (Отчет по объекту № 1-02/13. Госконтракт № АМ-02-34/14 от 10.06.2013 г.) (Свириденко \r\nМ.М., Падерин П.Г., Назаров Д.В., и др., 2015 г.). Комплект Госгеолкарты-1000 третьего поколения \r\nлиста R-45 (Норильск) с объяснительной запиской, в т.ч., в цифровом виде, издан картфабрикой \r\nФГУП «ВСЕГЕИ» в 2016 г. (Падерин П.Г., Деменюк А.Ф., Назаров Д.В., Чеканов В.И. и др., 2016 \r\nг.).\r\nНепосредственно в площади современного хвостохранилища Талнахской обогатительной \r\nфабрики изучение геологического строения верхней части разреза, сложенного четвертичными \r\nотложениями, поиски и разведку строительных материалов (песков штукатурных и для бетонов, \r\nпесчано-гравийных смесей для бетонов) проводила Нерудная поисково-разведочная партия \r\nНорильской КГРЭ Красноярского ГУ в 1964-1965 гг. и в 1970-1972 гг. (Максудов А.В., 1965 г., № \r\nотчета в Красгеолфонде - 14014; Максудов А.В., Булгаков С.Ф., Амосов Ю.Н., 1972 г., № отчета в \r\nКрасгеолфонде - 18025).\r\n2.2 Гидрогеологическая изученность\r\nСистематическое региональное гидрогеологическое изучение Норильского промрайона \r\nначалось в 50-60 годах ХХ века и заключалось в проведение обзорного и среднемасштабного \r\nкартографирования масштабов 1:1000000-1:200000-1:100000. На этом этапе работы выполнялись, \r\nв основном, районе Норильского плато и в левобережной части долины р. Норильской.\r\nВ районе северо-западной оконечности Хараелахского плато (правобережная часть долины \r\nр. Норильской) гидрогеологические работы начались с открытием медно-никелевых \r\nместорождений Талнахского рудного узла. В 1962-1963 гг. здесь проведены геологическая съемка \r\nм-ба 1:10000 и гидрогеологическая съемка м-ба 1:25000 (Цывьян Л.К., Вожов В.И., Дюжиков О.А.). \r\nСоставлены гидрогеологическая и мерзлотная карты м-ба 1:25000 и предложены первые схемы \r\nгидрогеологической стратификации и гидродинамики района. С 1961 г. по 1967 г.на территории \r\nТалнахского рудного узла проводились детальные гидрогеологические исследования м-ба 1:10000 \r\nпри разведке месторождений (Михалев Г.Л., Гроль Г.В., Могилевцев В.А.).\r\nВ 1964-1965 гг. в правобережной части долины р. Норильской, в пределах листа R-45-XXIII￾XXIV, силами Норильской комплексной геологоразведочной экспедиции (КГРЭ) Красноярского \r\nгеологического управления проведена гидрогеологическая съемка м-ба 1:200000, являющаяся \r\nединственным завершенным региональным исследованием гидрогеологических условий \r\nтерритории (Вожов В.И., Кузьмин Е.Е., Иогин С.М., 1966 г.). Результатом этих работ явилось \r\nсоставление гидрогеологической, мерзлотной, гидрохимической и гидродинамической карт м-ба \r\n1:200000.", "[стр. 13]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n7\r\nВзам. Инв. № Подп. и дата\r\n11\r\nВ 1991-1995 гг. Норильской КГРЭ проведено геолого-экологическое картирование \r\nНорильского района и прилегающих территорий м-ба 1:1000000 в площади листов R-45-В,-Г \r\n(Мельников Ю.О. и др., 2011 г.). \r\nВ 1993-2000 гг. в площади листов R-45-79-82; -91-94; -103-106; -115-118 (листы м-ба \r\n1:100000, покрывающие территорию Норильского рудного района), была проведена комплексная \r\nгидрогеологическая и инженерно-геологическая съемка м-ба 1:200000 (Ковпий А.Н., Мельников \r\nЮ.О., Островский Л.А., 2011 г.). \r\nБолее детальное гидрогеологическое изучение выполнялось на участках поисков и разведки \r\nподземных вод. Поисковые работы на воду для водоснабжения Талнахского промышленного \r\nкомплекса проведены в 1966-1968 гг. в районе гряды Лесной (занята ныне ТОФ и районом Талнах), \r\nа также в долине р. Листвянка – правого притока р. Норильской (Могилевцев В.А., Чеблукова Л.Б., \r\nИогин С.М., 1968 г.). В 1965-1972 гг. были разведаны запасы подземных вод Талнахского \r\nместорождения в талике эрозионно-тектонической долины р. Талнах (Рогинец И.И., Петраков В.В., \r\n1972 г.). Проведенные в 1996-1997 гг. поиски и поисково-оценочные работы в долине р. Хараелах \r\nдля водоснабжения рудника Скалистый по экономическим причинам были завершены с \r\nотнесением оцененных запасов к забалансовым (Келеп Г.П., Тетерюк В.А., Яруллин Т.Н., 1998 г.).\r\nДостаточно полные сведения о гидрогеологических и геокриологических условиях района \r\nданы в отчетах Норильской КГРЭ «Гидрогеологические исследования на Талнахском и \r\nЕргалахском месторождениях подземных вод с переоценкой запасов на участках действующих \r\nводозаборов (по состоянию на 01.01.1997 г.) (Яковлев А.О., Маркович Р.Я., Королева С.В., 1997 г.) \r\nи ПГП «Норильскгеология» «Отчет о поисках и поисково-оценочных работах в долине р. Хараелах \r\nна пресные подземные воды в период 1996-1997 г.г.» (Келеп Г.П., Маркович Р.Я., Яруллин Т.Н., \r\n1998 г.). \r\nС 1995 г. и по настоящее время на площади Норильского промрайона и отдельных его \r\nобъектов ведутся работы по изучению режима подземных вод, экзогенных геологических \r\nпроцессов, техногенного загрязнения подземных вод и т.д. (Гареев А.Р., Багинян М.К., Куприянов \r\nД.С., и др., 2007 г.; Стрекалов М.М., Ковпий А.Н., Куприянов Д.С., и др., 2002 г.).\r\n2.3 Инженерно-геологическая изученность\r\nНачиная с 1965 г., по договору с Норильской КГРЭ Красноярского ГУ, комплексные \r\nмерзлотные и инженерно-геологические исследования территории выполнялись кафедрой \r\nгрунтоведения и инженерной геологии Геологического факультета МГУ.", "[стр. 14]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n8\r\nВзам. Инв. № Подп. и дата\r\n12\r\nРезультаты исследований излагались в промежуточных отчетах (1967 г., 1969 г., 1970 г.) и \r\nв окончательном отчете 1975 г. (Голодковская Г.А., Демидюк Л.М., Шаумян Л.В., 1975 г., №№ \r\nКрасгеолфонда – 17620 и 19308). \r\nРисунок 2.1 – Инженерно-геологическая и поисково-разведочная в четвертичных \r\nотложениях изученность участка хвостохранилища ТОФ\r\nВ 1977 г., институтом «Норильскпроект» проводились инженерные изыскания под \r\nстроительство объектов оборотного водоснабжения в районе озера Хараелах (пруд-окислитель) и \r\nкарьера «Дальний».", "[стр. 15]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n9\r\nВзам. Инв. № Подп. и дата\r\n13\r\nВ 2003 г. также институтом «Норильскпроект» были выполнены инженерно-геологические \r\nизыскания стадии предпроектной документации на проектируемой площадке фильтрующей дамбы \r\nхвостохранилища ТОФ. В 2008–2009 гг. Партией изыскательских работ ООО «Норильскгеология» \r\nвыполнялись изыскания под фильтрующую дамбу нового хвостохранилища ТОФ. \r\nВ 2011-2012 гг. ЗАО «КБК» в рамках объекта «Реконструкция и техническое \r\nперевооружение ТОФ с увеличением мощности до 16 млн. т/год» на стадии проектной \r\nдокументации выполнялись инженерно–геологические изыскания, в т.ч. и непосредственно в \r\nконтуре хвостохранилища. \r\nВ 2020-2021 гг. АО «КБК» выполняло изыскания с целью уточнения гидрогеологических, \r\nгеокриологических условий площадки нижнего бьефа низовой дамбы хвостохранилища ТОФ; \r\nуточнения гидрогеологические условия низовой водоудерживающей дамбы хвостохранилища \r\nТОФ; оценки влияние техногенного объекта на химический состав подземных и поверхностных \r\nвод нижнего бьефа.\r\nВ целом изученность инженерно-геологических и геокриологических условий площадки \r\nхвостохранилища ТОФ оценивается достаточно высокой степенью. Вместе с тем, \r\nразновременность и некоторая мозаичность ранее проведенных работ не позволяет использовать \r\nвесь массив полученных данных для характеристики условий. Прежде всего это касается \r\nгидрогеологических условий, физико-механических свойств и температуры многолетнемерзлых \r\nгрунтов, инженерно-геокриологических процессов, использование материалов которых \r\nограничено, согласно п. 6.1.7 СП 47.13330.2016, давностью 2 года. Объем анализа данных буровых \r\nработ составит 50 % от объема бурения 2011 г. и весь объем 2020 г., т.е.,: (6718 пм * 0,5) + 340 пм \r\n= 3699 пм.\r\nОбщая геолого-гидрогеологическая, инженерно-геологическая и геокриологическая \r\nизученность района и объекта изысканий достаточно высокая, что позволяет оценивать те или иные \r\nусловия и геологическое строение территории на основании фактического материала, полученного \r\nбольшей частью непосредственно по объекту изысканий.", "[стр. 16]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n10\r\nВзам. Инв. № Подп. и дата\r\n14\r\n3 Краткая физико-географическая,геоморфологическая, геологическаяи \r\nгидрогеологическая характеристики района работ\r\n3.1 Физико-географическая характеристика\r\nВ административном отношении участок изысканий расположен в Красноярском крае, в \r\nНорильском промышленном районе в пределах городского округа краевого подчинения г. \r\nНорильск. Площадка хвостохранилища локализована в междуречье рр. Томулах и Хараелах, в 5 км \r\nсеверо-западнее г. Талнах.\r\nРисунок 3.1 – Обзорная схема расположения хвостохранилища ТОФ\r\nВ геоморфологическом отношении участок работ (хвостохранилище ТОФ) приурочен к \r\nХантайско-Рыбнинской троговой ложбине Среднесибирского плоскогорья. Троговая ложбина в", "[стр. 17]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n11\r\nВзам. Инв. № Подп. и дата\r\n15\r\nдолине р. Норильской и оз. Пясино занята поверхностью вальковской озерно-ледниковой равнины \r\n(Падерин П.Г. и др., 2016 г.) высотой 60-80 м над уровнем моря. Горное обрамление в строении \r\nучастка не участвует. Участок работ – хвостохранилище НМЗ - локализован в бассейне р. Буровой, \r\nправого притока р. Быстрой, правого притока р. Юж. Ергалах.\r\nРельеф собственно участка хвостохранилища ТОФ, как искусственного техногенного \r\nобъекта, существенно преобразован при его строительстве и эксплуатации – представлен секциями \r\nчаши равнинного намывного хвостохранилища и пруда-отстойника с ограждающими дамбами, \r\nзанимающими общую площадь 10,95 км2, заложенными на первичном рельефе вальковской \r\nравнины. Относительные высоты насыпных форм рельефа достигают 9-18 м.\r\n3.2 Климатическая характеристика\r\nРайон работ характеризуется крайне суровым климатом субарктического типа. Зима здесь \r\nдолгая и холодная (средняя температура января минус 26,9°C, см. таблица 3.1). Характерной \r\nособенностью зимы является частое установление морозной погоды в совокупности с сильными и \r\nочень холодными ветрами (метелями). Период устойчивых морозов длится около 280 дней в году, \r\nпри этом отмечается более 130 дней с метелями. Климатическая зима длится с начала второй \r\nдекады сентября по первую декаду мая. Устойчивые отрицательные среднемесячные температуры \r\nотмечаются с октября по май включительно. Снеговой покров сохраняется от 7,5 до 9 месяцев в \r\nгоду. Лето короткое (с конца июня по конец августа), прохладное (10,7°C, наиболее теплый месяц \r\nиюль со среднемесячной температурой 14,3°C) и пасмурное. Климатическое лето наступает лишь \r\nв отдельные тёплые годы. \r\nТаблица 3.1 – Климатическая характеристика района работ\r\nКлимат Норильска \r\nПоказатель Янв. Фев. Март Апр. Май Июнь Июль Авг. Сен. Окт. Нояб. Дек. Год \r\nАбсолютный максимум, °C −3,0 −2,0 7,4 10,5 22,8 31,0 32,2 28,7 20,6 9,6 3,1 −1,0 32,2\r\nСредний максимум, °C −23,6 −23,9 −18,4 −10,0 −1,7 10,4 18,2 15,0 6,9 −6,7 −16,9 −21,6 −6,2\r\nСредняя температура, °C −26,9 −27,2 −21,9 −13,9 −4,8 7,0 14,3 11,4 4,0 −9,5 −20,2 −25,1 −9,6\r\nСредний минимум, °C −30,7 −31,0 −26,4 −18,5 −8,4 3,2 10,0 7,6 1,2 −12,5 −23,9 −28,9 −13,2\r\nАбсолютный минимум, °C −53,1 −52,0 −46,1 −38,7 −26,8 −9,8 0,4 −1,0 −14,0 −36,0 −43,1 −51,0 −53,1\r\nНорма осадков, мм 27 27 26 26 31 41 44 54 40 42 35 33 427\r\nИсточник: Weatherbase", "[стр. 18]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n12\r\nВзам. Инв. № Подп. и дата\r\n16\r\nГодовые суммы осадков колеблются от 182 мм (1978 г.) до 645 мм (2007 г.), \r\nсреднемноголетнее их количество – 427 мм (данные за период 1975-2019 гг., ресурс \r\nhttp://www.pogodaiklimat.ru/history/23078_2.htm). Большая часть атмосферных осадков расходуется \r\nна поверхностный сток. В зимнюю межень речной сток значительно уменьшается. Многие реки и \r\nручьи промерзают зимой полностью, широко развиты русловые наледи. \r\nСредняя дата образования устойчивого снежного покрова – 30 сентября, средняя дата \r\nразрушения устойчивого снежного покрова – 22 мая. Высота снежного покрова в равнинной части \r\nможет достигать 8-9 м. Плотность снежного покрова в пределах района относительно высока и \r\nсоставляет в среднем 0,3-0,5 г/см3\r\n, запасы влаги в снеге – 140-170 мм.\r\nСреднегодовая температура воздуха в Норильске равна −9,6°C, годовая амплитуда \r\nабсолютных температур - 96°C. Среднегодовая относительная влажность воздуха - около 76%. \r\nСредняя многолетняя величина атмосферного давления 750 мм рт. ст. Среднегодовая скорость \r\nветра 6 м/с. Полярный день в Норильске длится с 20 мая по 24 июля, полярная ночь - с 30 ноября \r\nпо 13 января. \r\nНа основе анализа природных факторов, инженерно-геологические условия территории \r\nразмещения объекта относятся к III категории сложности по совокупности геоморфологических, \r\nгеологических и сейсмических условий и распространения экзогенных процессов (СП 11-105-97, \r\nчасть I, приложение Б).\r\nСогласно СНиП 23-01-99 «Строительная климатология», по климатическому \r\nрайонированию территория относится к климатическому подрайону 1Г (табл. А1), по суровости \r\nклимата на территории северной строительно-климатической зоны район относится к наиболее \r\nсуровым (табл. А2).\r\nТерритория Норильского промышленного района относится к Енисей-Путоранскому \r\nгеокриологическому региону. Согласно СП11-105-97 часть IV (прил. Л), район проведения \r\nизысканий расположен в области сплошного распространения многолетнемерзлых грунтов.\r\n3.3 Гидрографическая характеристика района работ.\r\nПлощадка хвостохранилища ТОФ принадлежит гидрографической сети бассейна р. Пясина. \r\nПлощадка находится в 5 км юго-восточней южной оконечности оз. Пясино и в 6,8 км восточнее \r\nустья правого рукава дельтовой части р. Норильская, впадающей в озеро. Хвостохранилище \r\nрасполагается на междуречном пространстве правых притоков р. Норильской: его огибают с юга (в \r\n200-700 м) - р. Хараелах (Еловая) (рисунок 2.3), с севера (в 400-600 м) – р. Томулах (Муксунка) и \r\nее притоки. Ближайшее расстояние от низовой дамбы хвостохранилища до р. Норильская - 3,1 км.", "[стр. 19]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n13\r\nВзам. Инв. № Подп. и дата\r\n17\r\nВодные отметки оз. Пясино, устья рр. Норильская и Хараелах – 28 м. абс. \r\nРека Норильская в нижнем течении имеет ширину до 400-700 м, глубину до 2,5 м и твердое \r\nпесчано-галечное дно. За 12 км до впадения в оз. Пясино русло становится многорукавным, \r\nобразует дельту шириной до 8-10 км. \r\nРека Хараелах полной длиной 47 км на участке течения вдоль южной дамбы \r\nхвостохранилища имеет многорукавное валунно-галечное русло с шириной рукавов до 20-30 м \r\n(рисунок 2.3).\r\nРисунок 3.2 – Долина р. Хараелах. Справа – площадка хвостохранилища ТОФ, вдали – р. \r\nНорильская\r\nРежим рек обусловлен их атмосферным питанием за счет дождей и талых снеговых вод. \r\nВесеннее половодье довольно длительное и приходится на июнь. Максимальные расходы воды \r\nнаблюдаются в первой декаде июня, через 10-15 дней после начала половодья (на р. Хараелах – до \r\n43,4 м3/с). Быстрое таяние снега в конце мая - начале июня и сезонное оттаивание \r\nмноголетнемерзлых пород обуславливают быстрый и высокий подъем воды в реках. Основная доля \r\nгодового стока (до 95 %) приходится на период с июня по сентябрь. В июле–августе сток рек \r\nобычно резко понижается. Летне-осенняя межень непродолжительна, наступает в конце августа -\r\nначале сентября, прерывается дождевыми паводками. После наступления ледостава на реке \r\nустанавливается зимняя межень, продолжающаяся большую часть года (с сентября по май). Мелкие \r\nреки в зимний период промерзают полностью, в р. Хараелах в период с января по март речной сток \r\nтакже отсутствует.", "[стр. 20]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n14\r\nВзам. Инв. № Подп. и дата\r\n18\r\nОзерность залесенного и закустаренного междуречья рек Хараелах и Муксунки в нижнем \r\nбьефе хвостохранилища ТОФ, оценочно достигает 10-15 %. Озерные водоемы небольшие по \r\nразмерам: округлые (аласовые, термокарстовые) – диаметром до 200-400 м, развиты в пойменной \r\nчасти долины р. Норильская. Глубина озер от 0,5 до 1,4 м. В связи с высокой озерностью и \r\nувлажненностью проходимость территории нижнего бьефа хвостохранилища в летнее время для \r\nпешего передвижения очень плохая, для автомобильного транспорта – непроходимая без \r\nспециальной подготовки пути движения. В зимнее время, с промерзанием водоемов и сезонно￾талого слоя (СТС), проходимость улучшается.\r\nИскусственным водным объектом является отстойный пруд хвостохранилища ТОФ. \r\nРазмеры его в границах ограждающих дамб: по фильтрующей дамбе – 1950 м, по низовой \r\nводоудерживающей ограждающей дамбе – 1600 м, ширина по расстоянию между дамбами – 450 м, \r\nширина водной поверхности – 250-420 м. Площадь отстойного пруда – 1,08 км2, объем воды при \r\nНПУ=45,5 м. абс составляет 1,7 млн. м3, уровень мертвого объема (УМО) - 40,5 м. абс (рисунок \r\n3.2). По количеству выпадающих на площадь отстойного пруда среднемноголетних жидких \r\nатмосферных осадков (179 мм за 4 месяца), он получает внешнее атмосферное питание в объеме \r\n193320 м3 или 1611 м3/сут (испарение и поступление от снеготаяния не учтены).\r\nРисунок 3.3 – Отстойный пруд хвостохранилища ТОФ, низовая и фильтрующие дамбы. Вдали –\r\nустье р. Норильской и оз. Пясино", "[стр. 21]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n15\r\nВзам. Инв. № Подп. и дата\r\n19\r\n3.4 Техническая характеристика объекта исследований\r\nПлощадка хвостохранилища ТОФ в современных границах размещена на месте \r\nнедействующего техногенного объекта - пруда-окислителя ТОФ. В 400-500 м восточнее верховой \r\nдамбы располагается площадь отработанного карьера песчано-гравийной смеси «Дальний». \r\nХвостохранилище удалено на 4,8-8,5 км (по крайним точкам) по азимуту 300° от Талнахской \r\nобогатительной фабрики (рисунок 2.5).\r\nРисунок 3.4 – Общая ситуация района хвостохранилища ТОФ (длина линии – 1000 м\r\nОбщая площадь хвостохранилища ТОФ в контуре ограждающих дамб – 10,95 км2\r\n, в контуре \r\nI очереди – 7,2 км2\r\n, площадь отстойного пруда – 1,08 км2\r\n. Водосборная площадь объекта \r\nсоответствует его площади по ограничивающим дамбам – 10,95 км2\r\n. \r\nПротяженность всего хвостохранилища по длинной оси (СЗ-ЮВ) – 4,3 км, по короткой оси \r\n(ЮЗ-СВ) – 3,1 км. Периметр дамб I очереди вместе с отстойным прудом – 10,2 км, периметр \r\nвключая II очередь – 12,5 км. Высота дамб от 7 до 20 м.\r\nПроектная полезная емкость хвостохранилища - 230 млн. т хвостов гидрометаллургического \r\nпредела концентратов руд. Согласно п. 4 ТЗ (приложение А), класс опасности размещаемых \r\nотходов – V (практически неопасные отходы).\r\nРасчетный срок эксплуатации – 20 лет. Начало опытно-промышленной эксплуатации I \r\nочереди хвостохранилища – 2017 г.\r\nАбсолютные отметки дневной поверхности гребней дамб колеблются в пределах: верховой \r\n– 60-70-80 м. абс, фильтрующей – 55-60 м. абс, низовой – 45-50 м. абс. Отметки, днища чаши", "[стр. 22]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n16\r\nВзам. Инв. № Подп. и дата\r\n20\r\nхвостохранилища – от 50-60 м. абс у фильтрующей дамбы до 60-65 м. абс у верховой дамбы; днища \r\nпруда отстойника – 45-55 м. абс. \r\nВодяная пульпа хвостов гидрометаллургического предела концентратов руд поступает в \r\nчащу хвостохранилища I очереди по трубопроводу длиной 6,7 км от Талнахской обогатительной \r\nфабрики. Твердая фаза пульпы осаждается на намывном пляже восточной части верховой дамбы \r\nхвостохранилища, отходящая от хвостов жидкая фаза фильтруется через фильтрующую дамбу в \r\nотстойный пруд. Трубопровод сооружен из труб фирмы «Сомэкс», футерованы изнутри \r\nполимерным составом.\r\nИнфильтрат отстойного пруда забирается плавучей насосной установкой (ПНУ компании \r\nEngineering Dobersek GmbH) и подается на насосную станцию оборотной воды (насосные агрегаты \r\nфирмы Warman), откуда по водоводу длиной 7,5 км направляется обратно на ТОФ в качестве \r\nоборотного водоснабжения. \r\nХарактеристики дамб отстойного пруда:\r\n- низовая водоудерживающая ограждающая дамба – протяженность 1600 м, ширина по \r\nгребню - 20 м, высота – до 20 м. Каменно-набросная, тало-мерзлая.\r\n- фильтрующая дамба – протяженность 1950 м, ширина по гребню 15 м, высота – 4,0 м. \r\nМатериал - каменно-набросная с фильтрующими вставками, талая.\r\nДно отстойного пруда и откосы ограждающих его дамб гидроизолированы геомембраной \r\n(полиэтиленовая пленка толщиной 1,5 мм), уложенной на геоматах согласно проекта \r\nстроительства.\r\nПо ограждающим дамбам хвостохранилища установлены опоры освещения с шагом 35 м. \r\nПо гребню и подножию низовой и верховой дамб проходят технологические дороги из насыпного \r\nгрейдированного грунта. В тело дамб уложено 4,5 млн. м3\r\nгрунта из песчано-гравийной смеси и \r\nболее 2 млн. м3\r\n- скальной обломочной породы.", "[стр. 23]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n17\r\nВзам. Инв. № Подп. и дата\r\n21\r\n3.5 Географо-экономические условия производства работ.\r\nСогласно примечанию к п. 8в СБЦ-99 участок работ располагается на территории со \r\nспециальным режимом (экологически вредные территории, внутренние территории вредных цехов \r\nпредприятий металлургической промышленности), при выполнении изысканий на территории \r\nкоторых к ценам на полевые работы применяется коэффициент 1,25 (стр. 4 СБЦ-99).\r\nСогласно Приложения 2 СБЦ-99, продолжительность неблагоприятного периода года для \r\nпроизводства полевых инженерных изысканий на участке и в районе работ (широты Красноярского \r\nкрая 68°-72°) составляет 9 месяцев (с 10 сентября по 10 июня), что обуславливает применение к \r\nценам на изыскательские работы коэффициента 1,4 (табл. 2, стр. 4 СБЦ-99).\r\nРайонный коэффициент к заработной плате работников изыскательских партий, отрядов, \r\nприменяемый при производстве полевых работ на участке – 1,8 (прил. 4 СБЦ-99), соответственно, \r\nкоэффициент к итогу сметной стоимости изысканий – 1,4 (подпункт «д» пункта 8, табл. 3, стр. 10 \r\nСБЦ-99). \r\nПо природно-климатическим условиям производства работ г. Норильск и его окрестности \r\nотносятся к районам Крайнего Севера (прил. 5 СБЦ-99).\r\nСогласно подпункту «е» пункта 8 СБЦ-99, к итогу сметной стоимости изысканий \r\nприменяется коэффициент 1,50 (выполнение изысканий в районах Крайнего Севера). \r\nС учетом одновременного применения коэффициентов, указанных в подпунктах «д» и «е» \r\nпункта 8, общий повышающий коэффициент к итогу сметной стоимости изысканий определяется \r\nпутем суммирования единицы с дробными частями соответствующих коэффициентов таблицы 3 и \r\nподпункта «е». Отсюда, общий повышающий коэффициент к итогу сметной стоимости изысканий \r\nпо объекту составит 1+0,4+0,5 = 1,9.\r\n3.6 Современное состояние объекта изысканий\r\nВ пределах площади изысканий первичные естественно-природные мерзлотно￾гидрогеологические условия нарушены техногенным воздействием.\r\nДамбы хвостохранилища являются линейными сооружениями, сложенными насыпными \r\nгрунтами. Высота дамб от 7 до 20 м, ширина по верху – 8-10 м, по низу – до 40-70 м. Насыпные \r\nгрунты тела дамб представлены песчано-гравийным материалом речного аллювия и щебнисто￾глыбовыми разностями магматических пород триаса. Внутренние откосы и ложе чаши отстойного \r\nпруда гидроизолированы водонепроницаемой геомембраной, уложенной по геоматам.", "[стр. 24]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n18\r\nВзам. Инв. № Подп. и дата\r\n22\r\nПодстилающие ложе хвостохранилища ТОФ естественные геологические образования \r\nпредставлены верхней частью разреза аяклинских слоев (laQIII-IVak), сложенных супесчано￾суглинистых отложений с песчаными прослоями и с включениями мелкого рассеянного \r\nобломочного материала. Под аяклинскими слоями на глубинах более 21 м по южному флангу \r\nверховой дамбы (вдоль р. Хараелах) и более 5-14 м – по разделительной дамбе залегают \r\nобразования ермаковской толщи, представленные бурыми щебнистыми глинами и суглинками.\r\nВскрытая мощность рыхлых четвертичных отложений в площади хвостохранилища ТОФ \r\nизменяется от 1,8-4,0 м до 15,0-16,8 м (на участках низовой и фильтрующей дамб) и более 25 м (по \r\nразделительной и верховой дамбам). Соответственно, эти же глубины отвечают глубине кровли \r\nкоренных пород ложа долины. \r\nИзысканиями 2011 г. и 2020 г. в площади хвостохранилища были установлены природные \r\nталиковые зоны, приуроченные к долинам небольших ручьев и озер. \r\nВ створе низовой дамбы имеются 3 таких участка: \r\n- по скважине № 353 глубиной более 13 м, \r\n- по скважинам №№ 926 и ХТ-4809 шириной до 80-100 м и глубиной более 10 м, \r\n- по скважинам №№ 930, 931, 932 шириной 220-250 м и глубиной более 10 м. \r\nВ створе фильтрующей дамбы также имеются таликовые участки: \r\n- по скважинам №№ 957, 958 глубиной более 7 м, \r\n- по скважине № ХТ-4443 глубиной более 9,5 м, \r\n- по скважине № ХТ-4936 глубиной более 8 м. \r\nВ створе разделительной дамбы таликовый участок вскрыт скважиной № 360 с глубины 6 м, \r\nширина участка до 80 м. \r\nПо восточному флангу верховой дамбы также имеется ряд таликовых участков: \r\n- по скважинам №№ 865, 866 – подозерный талик глубиной до 6 м, шириной до 150 м; \r\n- по скважинам №№ 868, 869, 870 – глубиной до 6-9,5 м и шириной до 500 м, \r\n- по скважине № 871 подозерный талик глубиной более 15 м и шириной до 100 м; \r\n- по скважинам №№ 874, 365 – подозерный талик глубиной 6 м и шириной до 30 м;\r\n- по скважинам №№ 878, 879 (примыкание разделительной дамбы к верховой) – глубиной \r\nдо 11,7 м и шириной до 150 м. \r\nНа южном фланге верховой дамбы (вдоль р. Хараелах) также имеются локальные таликовые \r\nучастки ограниченной мощности: \r\n- по скважине № 845 в долине ручья – в интервале глубин 3,2-7,0 м; \r\n- в скважинах №№ 854, 855 в долине ручья – в интервале глубин 2,2-11,8 м.", "[стр. 25]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n19\r\nВзам. Инв. № Подп. и дата\r\n23\r\nЗа время после начала эксплуатации хвостохранилища ТОФ в 2017 г. произошло изменение \r\nсостояния мерзлотно-гидрогеологических условий площадки в сторону ее растепления. \r\nРастепляющее действие оказывает круглогодичный площадной намыв хвостовой пульпы в \r\nплощадь бывшего пруда-окислителя, формирование техногенных водоемов перед фильтрующей \r\nдамбой. Отепляющее действие оказывает и крупный непромерзающий искусственный водоем \r\nотстойного пруда, что способствует поддержанию и расширению природных таликовых зон под \r\nгидроизолированной чашей пруда. В такой схеме возможна прямая транзитная фильтрация \r\nотходящих из пульпы шламовых вод по таликовым зонам под фильтрующей дамбой и отстойным \r\nпрудом с разгрузкой под низовой дамбой в подозерных таликах нижнего бьефа.\r\n3.7 Экзогенные геологические, инженерно-геологические, криогенные \r\nпроцессы\r\nВ районе проведения работ широко проявлены экзогенные геологические, инженерно￾геологические и криогенные процессы, развитие и распространение которых необходимо \r\nкартировать и изучать в процессе инженерных изысканий и учитывать при проведении \r\nстроительных работ. Развитие процессов в горной части территории не определяет инженерно￾геологические условия площадки хвостохранилища, поэтому здесь они не рассматриваются.\r\nВ равнинной части района, являющейся областью относительной стабилизации, криогенные \r\nпроцессы отличаются большим разнообразием, в особенности в пределах Норильско-Рыбнинской \r\nравнины. На участках распространения сильнольдистых отложений (льдистостью свыше 0,4) \r\nшироко проявляется морозобойное растрескивание, приводящее к формированию на поверхности \r\nполигонально-блочного рельефа, а в трещинных зонах - грунтовых жил. На блоках широко \r\nраспространены пятна-медальоны и сезонные бугры пучения. Термокарст развит практически \r\nповсеместно вследствие преобладания в разрезе высокольдистых глинистых отложений. На ранних \r\nстадиях его развитие приводит к образованию термокарстовых воронок, а по завершении -\r\nтермокарстовых озер. Многие озера в пределах норильской равнины имеют термокарстовое \r\nпроисхождение, о чем свидетельствует их изометрическая форма, плоские котловины и \r\nнезначительная глубина. Для данного геоморфологического элемента процесс циклического \r\nвзаимопреобразования термокарстовых озер и инъекционных бугров пучения является основным \r\nрельефообразующим фактором.\r\nВ долинах рек, где функционируют подрусловые надмерзлотные или сквозные талики, через \r\nкоторые разгружаются напорно-безнапорные водоносные горизонты, развито наледеобразование.", "[стр. 26]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n20\r\nВзам. Инв. № Подп. и дата\r\n24\r\nАнтропогенная горнодобывающая, обогатительная металлургическая деятельность \r\nНорильского промрайона оказывает существенное влияние на преобразование природных сред и \r\nразвитие техногенных ландшафтов. Отходы добывающих и перерабатывающих предприятий \r\nпредставлены безрудными вскрышными породами, шламами, отвальными хвостами, \r\nмелкодисперсными взвесями в воде, пылью и газами. Твердые отходы складируются в отвалах, \r\nхвостохранилищах и отстойниках, суммарно занимающих около 7000 га площади Норильского \r\nпромрайона. Отвальные хозяйства сопровождаются развитием оползней. Хвостохранилища и\r\nотстойники опасны развитием техногенных подрусловых таликов и таликов в основаниях \r\nограждающих плотин и дамб, что чревато их разрушением с катастрофическими последствиями.\r\nТехногенное загрязнение почв токсичными газовыми и пылевыми выбросами, а также \r\nмеханические и химические факторы воздействия влияют на состояние растительного покрова до \r\nстепени его полной деградации. В результате незакрепленные почво-грунты в сезонно-талом слое \r\nмогут приобретать текучесть, придавая неустойчивость склонам, а также усиливать протаивание \r\nгрунтов, ослабляя основания сооружений.\r\n3.8 Специфические грунты\r\nК специфическим грунтам, распространенным в пределах площади изысканий, относятся \r\nтехногенные насыпные и намывные грунты, торф и многолетнемерзлые грунты.\r\n3.9 Краткая характеристика техногенных условий района\r\nВ районе изысканий практически вся промышленная деятельность осуществляется ПАО \r\n«Горно-металлургическая компания «Норильский никель» (ПАО «ГМК «Норильский никель», \r\nдобывающей и перерабатывающей медно-никелевые руды с высокими содержаниями \r\nплатиноидов, редких и рассеянных элементов. Рудная база Заполярного филиала ОАО «ГМК \r\n«Норильский никель», обеспечивается работой двух рудников («Заполярный», «Медвежий ручей») \r\nна Норильском и пяти («Маяк», «Комсомольский», «Октябрьский», «Таймырский», «Скалистый») \r\n- на Октябрьском и Талнахском месторождениях. Обогащение руд осуществляется Норильской и \r\nТалнахской обогатительными фабриками, выплавка металлов - Медном (МЗ) и Надеждинском \r\nметаллургическом (НМЗ) заводах. Открытым способом отрабатывается Кайерканское угольное \r\nместорождение.\r\nТалнахская обогатительная фабрика, сбрасывающая хвосты в исследуемое \r\nхвостохранилище, имеет производительность по переработке медно-никелевой руды до 10 млн. т в", "[стр. 27]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n21\r\nВзам. Инв. № Подп. и дата\r\n25\r\nгод. Основная масса богатых и медистых руд талнахских рудников «Маяк», «Комсомольский», \r\n«Октябрьский», «Таймырский» и «Скалистый» перерабатывается на Талнахской обогатительной \r\nфабрике. С пуском 3 очереди фабрики ее производительность возрастет до 18 млн. т в год. \r\nХвостохранилище ТОФ позволяет ежегодно складировать около 6 млн. т хвостов замкнутого \r\nоборота, что предполагает значительно снижение использования свежей воды и уменьшает \r\nвоздействие на окружающую среду.\r\nВ целом район г. Талнах, как и весь Норильский промрайон, характеризуется весьма \r\nинтенсивной техногенной нагрузкой, обусловленной деятельностью крупнейшего горно￾металлургического предприятия, оказывающего загрязняющее влияние по всем природным средам \r\nна очень большой площади.", "[стр. 28]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n22\r\nВзам. Инв. № Подп. и дата\r\n26\r\n4 Инженерно-геологическое, инженерно-гидрогеологическое \r\nрекогносцировочное обследование\r\nОбследование выполняется по стандартному комплексу работ, предусмотренному СБЦ-99 с \r\nвыделением технологических полевого и камерального этапов. \r\nПолевые работы заключаются в осмотре площади участка изысканий (хвостохранилища),\r\nприлегающей территории, визуальной оценке рельефа для возможностей передвижения персонала, \r\nтехники и размещения площадок буровых скважин, производство комплекса геологических, \r\nгеоморфологических, гидрогеологических, экологических и почвенных наблюдений по\r\nвыбранному маршруту (с ведением полевых записей), боковые маршруты для визуального \r\nобследования, сбор опросных сведений, выяснение условий производства изысканий и состояния \r\nобследуемой площади и сооружений. Документация полевого обследования сопровождается \r\nфотофиксацией всех точек наблюдений и их привязкой с помощью GPS-навигатора.\r\nКамеральные работы при подготовке к полевым работам выполняются для \r\nпредварительного ознакомления по картографическим и иным имеющимся материалам с районом \r\nи объектом работ, выбора направлений маршрутов. Камеральные работы завершающего этапа \r\nпроизводятся для обработки и систематизации записей в полевых дневниках, систематизации \r\nопросных сведений, составления каталога точек обследований, составления схематической \r\nинженерно-геологической (гидрогеологической) карты обследованной территории в оптимальном \r\nмасштабе, выделения участков для проведения более детальных исследований, оформления \r\nматериалов в увязке с данными предполевого дешифрирования, составления заключения об \r\nобследовании.\r\nКатегория сложности инженерно-геологических условий- III (табл. 7, СБЦ-99).\r\nКатегория по условиям проходимости местности - III (плохая) (табл. 8, СБЦ-99).\r\nОбследование проводится в виде линейных маршрутов по периметру хвостохранилища.\r\nПланируемая протяженность маршрутных наблюдений в районе низовой дамбы – 1,2 км, \r\nразделительной дамбы – 3,3 км, верховой дамбы – 4,7 км. Общая протяженность маршрутов –\r\n1,2+3,3+4,7 = 9,2 п. км.\r\nПодъезд к участку работ возможен в любое время года по дороге с щебенистым покрытием. \r\nПо верху дамб, ограждающих чашу хвостохранилища устроены технологические проезды, а также \r\nсъезды к подошве низовой дамбы. Съезды в чашу хвостохранилища не организованы.", "[стр. 29]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n23\r\nВзам. Инв. № Подп. и дата\r\n27\r\nДля проведения работ в зоне пляжа необходимо применение вездеходной техники или \r\nмалогабаритных переносных буровых установок, в связи с обводненностью толщи хвостовых \r\nсооружений и низкой несущей способностью.\r\nРисунок 4.1 – Схема расположения проектируемых инженерно-геологических скважин\r\nРекогносцировочные работы производилась октябре 2020 г, до установления постоянного \r\nснегового покрова.\r\nМаршруты инженерно-геодезической рекогносцировки привязывались к пикетажу \r\nобследуемых сооружений по вынесенным на местности проектным скважинам, по существующим \r\nархивным скважинам и при помощи навигационного GPS приемника.\r\nМаршрут 1 идет против хода пикетажа, в северо-западном направлении, проходит по \r\nнизовой дамбе от ПК 20+50 до ПК 5.\r\nНизовая дамба: Уровень ответственности – повышенный. Длина по гребню 2,8 км, ширина\r\nгребня 10 м, высота от уреза хвостохранилища– 4,0 м. Отметка гребня – 305 м. Материал - каменно￾набросная, талая (рисунок 4).", "[стр. 30]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n24\r\nВзам. Инв. № Подп. и дата\r\n28\r\nТочка маршрута: ПК20+50.\r\nПримыкание низовой дамбы к фильтрующей. Высота сооружения примерно 8 м, \r\nпредставлено свежеотсыпанными насыпными грунтами, сложенным глыбами, щебенистым \r\nгрунтом с супесчаным заполнителем. Грунт маловлажный. Насыпь естественно уплотнена. По \r\nверху дамбы проходил ЛЭП низкого напряжения, устроено освещение.\r\nПруд заполнен водой поверхность частично покрыта льдом. \r\nЛевый борт дамбы 2-х уровневый. Высота верхней полочки 5 м, ширина 4 м. Нижняя полка \r\n8 м. У подножия проходит технологическая дорога. Инженерно-геологические процессы не \r\nзафиксированы.\r\nРисунок 4.2 – Низовая дамба", "[стр. 31]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n25\r\nВзам. Инв. № Подп. и дата\r\n29\r\nРисунок 4.3 – Низовая дамба, левый борт\r\nРисунок 4.4 – Примыкание низовой дамбы к фильтрующей\r\nТочка маршрута: ПК15 (скв. 2ПН-1)\r\nПо оси низовой дамбы производится технологическая работа. Присутствуют навалы\r\nгрунта. Дорога отсыпана глинистым грунтом, тело дамбы сложено глыбовым грунтом, с \r\nпесчаным заполнителем. Левый борт дамбы 2-х уровневый, 6 м верхний уровень и нижняя \r\nполочка 8 м. Съезд на технологическую дорогу.", "[стр. 32]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n26\r\nВзам. Инв. № Подп. и дата\r\n30\r\nРисунок 4.5 – Низовая дамба\r\nРисунок 4.6 – Съезд на технологическую дорогу", "[стр. 33]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n27\r\nВзам. Инв. № Подп. и дата\r\n31\r\nРисунок 4.7 – Низовая дамба, правый борт\r\nТочка маршрута: ПК13+50 \r\nХарактер местности, сложение дамбы без изменений. С лева по ходу съезд с дамбы на \r\nтехнологическую дорогу к подножью дамбы.\r\nРисунок 4.8 –Точка маршрута: ПК11 (скв. 21-2)", "[стр. 34]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n28\r\nВзам. Инв. № Подп. и дата\r\n32\r\nЛевый борт дамбы двухуровневый, ширина полочек 4 м. У основания территория \r\nзаболочена. Правый борт дамбы – свежая отсыпка гравийно-галечниковым грунтом с супесчаным \r\nзаполнителем.\r\nРисунок 4.9 – Низовая дамба, левый борт", "[стр. 35]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n29\r\nВзам. Инв. № Подп. и дата\r\n33\r\nРисунок 4.10 – Низовая дамба, левый борт, съезд\r\nРисунок 4.11 – Низовая дамба, правый борт\r\nТочка маршрута: ПК10+20\r\nНа гребне дамбы сохранены оборудованные архивные скважины на всей территории \r\nдамбы. Ширина гребня дамбы – 30 м.", "[стр. 36]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n30\r\nВзам. Инв. № Подп. и дата\r\n34\r\nРисунок 4.12 – Архивные скважины Пк10\r\nТочка маршрута: ПК8\r\nОсь дамбы, поверхность отсыпана свежим техногенным грунтом, представленным \r\nщебенистым грунтом без заполнителя.\r\nРисунок 4.13 – Низовая дамба", "[стр. 37]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n31\r\nВзам. Инв. № Подп. и дата\r\n35\r\nРисунок 4.14 – Низовая дамба\r\nРисунок 4.15 – Низовая дамба, левый борт\r\nТочка маршрута: ПК5\r\nКонец низовой дамбы, примыкающий к ограждению дамбы высота правого борта 4-5 м, \r\nлевого 15 м, дамба отсыпана в 2 уровня.", "[стр. 38]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n32\r\nВзам. Инв. № Подп. и дата\r\n36\r\nНасыпь представлена щебенистым грунтом без заполнителя, ведутся строительные работы. \r\nпо расширению хвостохранилища.\r\nРисунок 4.16 – Конец низовой дамбы\r\nРисунок 4.17 – Конец низовой дамбы. Архивные скважины ОП-1, ОТ-1", "[стр. 39]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n33\r\nВзам. Инв. № Подп. и дата\r\n37\r\nРисунок 4.18 – Конец низовой дамбы\r\nМаршрут 2 идет по разделительной дамбе, против хода пикетажа, от ПК14 до ПК0. \r\nМаршрут проложен в северо-восточном направлении до примыкания разделительной дамбы к \r\nверховой дамбе.\r\nТочка маршрута: ПК13\r\nПравый борт отсыпан гравийным грунтом с песчаным заполнителем. У основания дамбы \r\nпульпа переработанной руды. Левый борт двухъярусный, отсыпан щебенистым грунтом с \r\nсупесчаным заполнителем. Берма (нижняя полочка) невыдержанная имеет неправильную форму. \r\nШирина гребня 15 м, высота 8 м.\r\nПо гребню дамбы устроен технологический проезд.\r\nПо левой стороне, по ходу маршрута, в бровке дамбы устроена ЛЭП низкого напряжения \r\nна бетонных опорах, с фонарем освещения на каждой опоре.\r\nПо правой стороне проложен наземный пульпопровод с организованными площадками \r\nвыпуска пульпы СВ-6 и СВ-5", "[стр. 40]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n34\r\nВзам. Инв. № Подп. и дата\r\n38\r\nРисунок 4.19 – Разделительная дамба\r\nРисунок 4.20 – Разделительная дамба", "[стр. 41]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n35\r\nВзам. Инв. № Подп. и дата\r\n39\r\nРисунок 4.21 – Вид на пляж\r\nТочка маршрута: ПК12, СВ6\r\nВыпуск пульпы, высота насыпи 8 м, насыпь представлена гравийным грунтом. Левый борт \r\nдамбы имеет одну берму неправильной формы, ширина 4 м.\r\nРисунок 4.22 – Разделительная дамба", "[стр. 42]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n36\r\nВзам. Инв. № Подп. и дата\r\n40\r\nРисунок 4.23 – Разделительная дамба\r\nРисунок 4.24 – Разделительная дамба, СВ-6\r\nТочка маршрута: ПК10\r\nПравый борт крутой, высотой 8 м, левый борт имеет широкую берму 5-6 м. У основания \r\nдамбы слева территория заболочена, распространены термокарстовые озёра. Насыпь \r\nпредставлена щебенистым грунтом с супесчаным заполнителем.", "[стр. 43]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n37\r\nВзам. Инв. № Подп. и дата\r\n41\r\nРисунок 4.25 – Разделительная дамба, левый борт заболоченная территория\r\nРисунок 4.26 – Гребень разделительной дамбы, технологический проезд", "[стр. 44]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n38\r\nВзам. Инв. № Подп. и дата\r\n42\r\nРисунок 4.27 – Разделительная дамба, правый борт, отложения пульпы\r\nТочка маршрута: ПК6 \r\nЛевый борт имеет два уровня, высота до 8 м, у основания навалы техногенного грунта. \r\nПравый борт крутой, высотой до 8 м, одноуровневый, насыпь представлена щебенистым грунтом \r\nс супесчаным заполнителем. У основания дамбы – отложения пульпы.\r\nРисунок 4.28 – Разделительная дамба", "[стр. 45]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n39\r\nВзам. Инв. № Подп. и дата\r\n43\r\nРисунок 4.29 – Разделительная дамба, правый борт\r\nРисунок 4.30 – Разделительная дамба, левый борт навалы техногенного грунта у основания\r\nТочка маршрута: ПК3, СВ-5\r\nВыпуск пульпы СВ-5 по правому борту. Габариты дамбы – без изменений. У оси левого \r\nборта встречаются навалы грунта. На ПК-0 - начало дамбы, конец верховой дамбой.", "[стр. 46]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n40\r\nВзам. Инв. № Подп. и дата\r\n44\r\nРисунок 4.31 – Разделительная дамба\r\nРисунок 4.32 – Разделительная дамба, правый борт выпуск пульпы СВ-5.", "[стр. 47]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n41\r\nВзам. Инв. № Подп. и дата\r\n45\r\nРисунок 4.33 – Разделительная дамба\r\nМаршрут 3 проложен по верховой дамбе, против хода пикетажа, проходит от конца \r\nверховой дамбы ПК46+50 до начала в ПК0. Первая часть маршрута проходит в южном\r\nнаправлении до автодороги на «Норильскгеологию», затем направление меняется на западное, и \r\nзавершается маршрут в начале верховой дамбы.\r\nТочка маршрута: ПК45\r\nВерховая дамба. Правый борт высотой 3м, представлен щебенистым грунтом с супесчаным \r\nзаполнителем. Левый борт высотой 5-6 м, ведутся планировочные работы. В 50 м расположена \r\nархивная скважина №15П1. \r\nПо левой стороне, по ходу маршрута, в бровке дамбы устроена ЛЭП низкого напряжения \r\nна бетонных опорах, с фонарем освещения на каждой опоре.\r\nПо правой стороне проложен наземный пульпопровод с организованными площадками \r\nвыпуска пульпы СВ-4 и СВ-3\r\nПо гребню дамбы проложена автодорога, у подошвы дамбы с полевой стороны дублер \r\nавтодороги. Далее в полевую сторону ведутся планировочные работы.\r\nСлева у подошвы дамбы – намывы пульпы.", "[стр. 48]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n42\r\nВзам. Инв. № Подп. и дата\r\n46\r\nРисунок 4.34 – Верховая дамба\r\nРисунок 4.35 – Верховая дамба\r\nРисунок 4.36 – Верховая дамба, правый борт", "[стр. 49]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n43\r\nВзам. Инв. № Подп. и дата\r\n47\r\nТочка маршрута: ПК42 (СВ4)\r\nВыпуск оформлен щебенистым грунтом. Высота насыпи 3-4 м. Левый борт состоит из \r\nдвух полочек, основание – естественный грунт, заболоченная территория. В 50 м архивная \r\nскважина 14р1.\r\nРисунок 4.37 – Верховая дамба, СВ-4\r\nРисунок 4.38 – Верховая дамба, СВ-4", "[стр. 50]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n44\r\nВзам. Инв. № Подп. и дата\r\n48\r\nРисунок 4.39 – Верховая дамба, левый борт\r\nТочка маршрута: ПК39\r\nХарактер местности размеры и состояние плотины – без изменений, на левой бровке \r\nархивные скважины 13т-1, 13П-1 3ликв.\r\nРисунок 4.40 – архивные скважины 13т-1, 13П-1 3ликв.", "[стр. 51]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n45\r\nВзам. Инв. № Подп. и дата\r\n49\r\nРисунок 4.41 – Верховая дамба, левый борт по ходу маршрута\r\nТочка маршрута: ПК33\r\nЛевый борт – насыпной щебенистый грунт с супесчаным заполнителем, высота 2-3 м. \r\nПравый борт – примыкание автодороги на карьер «Скальный», съезд к КПП, по левому борту \r\nведутся работы. Естественный рельеф – заболоченный.\r\nРисунок 4.42 – Верховая дамба, автодорога на карьер «Скальный»\r\nТочка маршрута: ПК34. По левому борту архивные скважины 12П, 12Т.", "[стр. 52]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n46\r\nВзам. Инв. № Подп. и дата\r\n50\r\nРисунок 4.43 – Верховая дамба, левый борт, архивные скважины\r\nРисунок 4.44 – Верховая дамба, правый борт\r\nТочка маршрута: ПК30+50\r\nВыпуск СВ-3 насыпь высотой 1,5 м представлена щебенистым грунтом с супесчаным \r\nзаполнителем. Слева борт с бермой шириной 4 м и высотой 2 м. У подошвы дамбы проходит \r\nавтодорога.", "[стр. 53]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n47\r\nВзам. Инв. № Подп. и дата\r\n51\r\nРисунок 4.45 – Верховая дамба, левый борт\r\nРисунок 4.46 – Верховая дамба\r\nТочка маршрута: ПК29+50. По левой бровке архивные скважины 10П и 10Т", "[стр. 54]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n48\r\nВзам. Инв. № Подп. и дата\r\n52\r\nРисунок 4.47 – архивные скважины 10П и 10Т\r\nТочка маршрута: ПК24. Высота насыпи увеличена, достигает 4м, представлена \r\nщебенистым грунтом с супесчаным заполнителем. По левому борту съезд на технологическую \r\nдорогу. Справа организован съезд в чашу хвостохранилища.\r\nРисунок 4.48 – Верховая дамба, правый борт", "[стр. 55]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n49\r\nВзам. Инв. № Подп. и дата\r\n53\r\nРисунок 4.49 – Верховая дамба\r\nРисунок 4.50 – Верховая дамба, левый борт, съезд на технологическую дорогу в чашу \r\nхвостохранилища", "[стр. 56]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n50\r\nВзам. Инв. № Подп. и дата\r\n54\r\nРисунок 4.51 – Верховая дамба. Архивные скважины 10Т, 10П\r\nТочка маршрута: ПК22. Слева у бровки дамбы архивные скважины 9Т, 9П\r\nНасыпь высотой 4 метра, шириной 10-15м.\r\nРисунок 4.52 – Верховая дамба. Архивные скважины 9Т, 9П", "[стр. 57]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n51\r\nВзам. Инв. № Подп. и дата\r\n55\r\nТочка маршрута: ПК20\r\nС левой стороны - узел переключения трубопроводов №2, за ним проходит автодорога. Три \r\nпульпопровода проходят в теле дамбы на правую сторону.\r\nРисунок 4.53 – Узел переключения трубопроводов №2\r\nТочка маршрута: ПК19 \r\nПо левую сторону съезд на технологическую дорогу к подножью верховой дамбы. Левый \r\nборт частично спланирован. Щебень, глыба.\r\nРисунок 4.54 – Опоры ЛЭП в юго-восточном углу хвостохранилища", "[стр. 58]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n52\r\nВзам. Инв. № Подп. и дата\r\n56\r\nРисунок 4.55 – Верховая дамба, съезд на технологическую дорогу\r\nТочка маршрута: ПК17 \r\nВысота дамбы около 6м, прилегающие площадки с двух сторон спланированы. Со стороны \r\nхвостохранилища, по правой бровке дамбы, обустроено ограждение из железобетонных блоков.\r\nРисунок 4.56 – Верховая дамба\r\nС левой стороны проходят 2 нитки пульпопроводов с опорами из железобетонных блоков и \r\nЛЭП с фонарями освещения", "[стр. 59]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n53\r\nВзам. Инв. № Подп. и дата\r\n57\r\nРисунок 4.57 – Верховая дамба. Задвижка СВ-1\r\nТочка маршрута: ПК14, скв \r\nПравый борт – щебенистый грунт основной склон 8м. берма- 1,5мшириной и 1,5м высотой. \r\nЛевый борт – основание естественная поверхность высота около15м.\r\nБлиже к ПК15, в плотную к трубопровотам, закреплена архивная скважина 7П-1 и 7Т(?)\r\nРисунок 4.58 – Верховая дамба. Архивные скважины", "[стр. 60]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n54\r\nВзам. Инв. № Подп. и дата\r\n58\r\nРисунок 4.59 – Верховая дамба, правый борт\r\nТочка маршрута: ПК9.\r\nВысота правого борта 10м. В основании пульпа. Левый борт 18м. в основании \r\nтехнологическая дорога и естественный рельеф, ширина основной площадки 30м. Насыпь \r\nпредставлена щебенистым грунтом с супесчаным заполнителем. Ведутся строительные работы. \r\nДалее по правому борту ведутся работы по планировке площадки, высота борта 1 м. Вдоль левого \r\nборта проходит трубопровод.\r\nРисунок 4.60 – Верховая дамба. СВ-1", "[стр. 61]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n55\r\nВзам. Инв. № Подп. и дата\r\n59\r\nРисунок 4.61 – Верховая дамба, левый борт\r\nРисунок 4.62 – Верховая дамба\r\nИнтервал маршрута: ПК4-ПК1\r\nБорта пологие, низкие, до 1-1,5м, в чаше локально пульпа 4. Естественный рельеф. Гребень \r\nдамбы переходит в технологическую дорогу шириной 35м. Трубы по левому и правому борту.", "[стр. 62]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n56\r\nВзам. Инв. № Подп. и дата\r\n60\r\nРисунок 4.63 – Верховая дамба\r\nРисунок 4.64 – Верховая дамба, левый борт", "[стр. 63]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n57\r\nВзам. Инв. № Подп. и дата\r\n61\r\nРисунок 4.65 – Верховая дамба, правый борт", "[стр. 64]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n58\r\nВзам. Инв. № Подп. и дата\r\n62\r\n5 Требования по охране труда и техники безопасности при проведении \r\nработ\r\nПри выполнении изыскательских работ необходимо руководствоваться требованиями ГОСТ \r\nР 12.3.048-2002, СНиП 12-03-2001 и СНиП 12-04-2002 и ведомственными инструкциями.\r\nРуководитель или ответственный исполнитель полевых работ до выезда на объект проверяет \r\nтехнику безопасности (инструктаж, экзамен) всех работников и наличие у них соответствующего \r\nудостоверения и прав ответственного ведения работ, а также наличие средств защиты и \r\nтранспортных средств, приспособленных для перевозок грузов и людей.\r\nК работе допускается персонал, прошедший обучение и инструктаж. Готовность буровой \r\nтехники к проведению работ, надежность и исправность бурового оборудования и инструментов, \r\nналичие и состояние ограждающих, защитных и предохранительных средств проверяет перед \r\nвыездом начальник партии и технический руководитель работ. Перед началом работ персонал \r\nпроходит дополнительный инструктаж на рабочих местах. \r\nКатегорически запрещается производство буровых и других земляных работ в охранной \r\nзоне ЛЭП, ЛЭС, подземных кабелей и других коммуникаций без письменного согласования мест \r\nбурения скважин с организациями, эксплуатирующими эти коммуникации.\r\nКаждое полевое подразделение должно иметь радиостанции для постоянной связи и \r\nполевую аптечку, а отдельные исполнители, работающие в отдалении, индивидуальные \r\nмедицинские пакеты.", "[стр. 65]\nИзм. Кол.уч. Лист № док. Подп. Дата\r\nЗФ-151/006-ИГИ2.1.3\r\nЛист\r\nИнв. № подл.\r\n59\r\nВзам. Инв. № Подп. и дата\r\n63\r\nТаблица регистрации изменений\r\nИзм.\r\nНомера листов (страниц) Всего \r\nлистов \r\n(страниц) \r\nв док.\r\nНомер \r\nдок.\r\nизме- Подп. Дата\r\nненных\r\nзаме￾ненных\r\nновых\r\nаннули￾рованных"]};
